ruleBookInfo.intro:
text.在线阅读已开放@href
<js>
url="https://bbs.fanfanc.com/"+result;
html=java.ajax(url);
java.setContent(html);
intro=String(java.getString("@@class.intro@html")).replace(/ 　　/g,"\n")
list=java.getElements("@@class.nav-wrap.0@li").toArray();
if(list.length>1){
	yuan="";
	for(i in list){
	text=list[i].text();
	yuan+="【"+i+"】"+text+"\n"
	}
xu=(book.getVariable("custom")==null||book.getVariable("custom")=="")?"0":book.getVariable("custom");
co=String(url).match(/ydn(\d+)/)[1];
header={
	"headers":{
		"Cookie":"pathid_"+co+"="+xu
		}
	}
java.put('coo',JSON.stringify(header))
laiyuan='当前来源【'+xu+'】';
u=url+'?pathid_'+xu+","+JSON.stringify(header)
java.put('url',u);
result='换源列表（点击设置书籍变量，输入序号，确认后刷新，可更改对应的源，默认为0）\n'+yuan+"\n"+laiyuan+'\n--------------\n'+intro;
	}else{
		java.put('url',url)
		result=intro;

		}
</js>

